from pathlib import Path
import json, shutil
import pandas as pd
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, PageBreak

ROOT=Path(__file__).resolve().parents[1]; RES=ROOT/'results'; WEB=ROOT/'dashboard/web'; DATA=WEB/'data'; DATA.mkdir(parents=True,exist_ok=True)
files=['metrics_portfolio_vs_index.csv','weights.csv','risk_contribution.csv','metrics_by_asset.csv','optimization_weights.csv','optimization_summary.csv','efficient_frontier.csv','performance_base100.csv']
for f in files:
    df=pd.read_csv(RES/f)
    if 'date' in df.columns: df['date']=df['date'].astype(str)
    (DATA / f.replace('.csv','.json')).write_text(df.to_json(orient='records',force_ascii=False),encoding='utf-8')

m=pd.read_csv(RES/'metrics_portfolio_vs_index.csv').set_index('Unnamed: 0'); w=pd.read_csv(RES/'weights.csv'); r=pd.read_csv(RES/'risk_contribution.csv'); a=pd.read_csv(RES/'metrics_by_asset.csv')
styles=getSampleStyleSheet(); styles.add(ParagraphStyle(name='BodyFr',parent=styles['BodyText'],fontName='Helvetica',fontSize=9.5,leading=13,textColor=colors.HexColor('#172B3A'))); styles.add(ParagraphStyle(name='H1Fr',parent=styles['Heading1'],fontName='Helvetica-Bold',fontSize=19,textColor=colors.HexColor('#243D4D'),spaceAfter=8)); styles.add(ParagraphStyle(name='H2Fr',parent=styles['Heading2'],fontName='Helvetica-Bold',fontSize=13,textColor=colors.HexColor('#176B78'),spaceBefore=8,spaceAfter=5))
out=ROOT/'reports/rapport_portefeuille_risque.pdf'; doc=SimpleDocTemplate(str(out),pagesize=A4,rightMargin=16*mm,leftMargin=16*mm,topMargin=15*mm,bottomMargin=15*mm)
story=[Paragraph("Risque et performance d’un portefeuille d’actions",styles['H1Fr']),Paragraph("Rapport analytique — Données simulées",styles['H2Fr']),Paragraph("Question de gestion : le portefeuille compense-t-il le risque qu’il prend par rapport à son indice de référence, où le risque est-il concentré et comment rééquilibrer les positions ?",styles['BodyFr']),Spacer(1,8)]
story += [Paragraph('1. Données et méthode',styles['H2Fr']),Paragraph("L’étude utilise 104 clôtures hebdomadaires simulées sur la période du 1er novembre 2024 au 23 octobre 2026, dix titres fictifs et l’indice IDX. Les rendements, la volatilité, le ratio de Sharpe, le drawdown, le bêta, l’alpha et la VaR historique sont calculés à partir des résultats versionnés dans results/. Les optimisations sont long-only, avec une limite de 35 % par titre, et restent des repères in-sample.",styles['BodyFr']),Spacer(1,5)]
data=[['Indicateur','Portefeuille','Indice IDX'],['Rendement annualisé',f"{m.loc['portefeuille','rendement_annualise']:.1%}",f"{m.loc['indice_IDX','rendement_annualise']:.1%}"],['Volatilité annualisée',f"{m.loc['portefeuille','volatilite_annualisee']:.1%}",f"{m.loc['indice_IDX','volatilite_annualisee']:.1%}"],['Ratio de Sharpe',f"{m.loc['portefeuille','ratio_sharpe']:.2f}",f"{m.loc['indice_IDX','ratio_sharpe']:.2f}"],['Drawdown maximum',f"{m.loc['portefeuille','drawdown_max']:.1%}",f"{m.loc['indice_IDX','drawdown_max']:.1%}"],['Bêta vs IDX',f"{m.loc['portefeuille','beta_vs_IDX']:.2f}",'1,00'],['VaR 95 % hebdo',f"{m.loc['portefeuille','VaR_95_hebdo']:.1%}",f"{m.loc['indice_IDX','VaR_95_hebdo']:.1%}"]]
t=Table(data,colWidths=[70*mm,45*mm,45*mm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#243D4D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#DDE3E7')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F8F9')]),('ALIGN',(1,1),(-1,-1),'RIGHT'),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6)])); story += [t,PageBreak()]
story += [Paragraph('2. Performance et risque',styles['H2Fr']),Paragraph("Le portefeuille affiche un rendement annualisé supérieur à l’indice (13,0 % contre 11,4 %), mais une volatilité et un drawdown plus élevés. Le ratio de Sharpe est proche de celui de l’indice : l’excédent de rendement ne rémunère donc que marginalement le risque additionnel. Le bêta de 1,03 indique une sensibilité légèrement supérieure au marché de référence.",styles['BodyFr']),Spacer(1,8),Paragraph('3. Concentration du risque',styles['H2Fr']),Paragraph("La contribution au risque est plus concentrée que les poids. AFBK représente 28,5 % de la valeur mais 34,9 % du risque ; CLDX représente 14,1 % de la valeur et 21,2 % du risque. Ensemble, ils pèsent 42,6 % de la valeur et 56,1 % du risque. Cette asymétrie justifie une revue des limites par position et par secteur.",styles['BodyFr']),Spacer(1,6)]
rc=r.sort_values('contribution_risque',ascending=False).head(5); data=[['Titre','Poids','Part du risque']]+[[x.ticker,f'{x.poids:.1%}',f'{x.contribution_risque:.1%}'] for x in rc.itertuples()]; t=Table(data,colWidths=[60*mm,50*mm,50*mm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#243D4D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#DDE3E7')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F8F9')]),('ALIGN',(1,1),(-1,-1),'RIGHT'),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6)])); story += [t,PageBreak()]
story += [Paragraph('4. Allocation et optimisation',styles['H2Fr']),Paragraph("L’optimisation de variance minimale réduit fortement la volatilité mais produit un rendement historique négatif ; l’optimisation de Sharpe maximal augmente le rendement et le risque. Ces résultats sont in-sample et ne doivent pas être considérés comme une allocation recommandée sans validation hors échantillon.",styles['BodyFr']),Spacer(1,6)]
opt=pd.read_csv(RES/'optimization_summary.csv'); data=[['Scénario','Rendement','Volatilité','Sharpe']]+[[x[0],f"{x[1]:.1%}",f"{x[2]:.1%}",f"{x[3]:.2f}"] for x in opt.itertuples(index=False, name=None)]; t=Table(data,colWidths=[65*mm,45*mm,45*mm,35*mm]); t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),colors.HexColor('#243D4D')),('TEXTCOLOR',(0,0),(-1,0),colors.white),('GRID',(0,0),(-1,-1),.25,colors.HexColor('#DDE3E7')),('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#F7F8F9')]),('ALIGN',(1,1),(-1,-1),'RIGHT'),('FONTNAME',(0,0),(-1,0),'Helvetica-Bold'),('FONTSIZE',(0,0),(-1,-1),9),('BOTTOMPADDING',(0,0),(-1,-1),6),('TOPPADDING',(0,0),(-1,-1),6)])); story += [t,PageBreak()]
story += [Paragraph('5. Rééquilibrage et recommandations',styles['H2Fr'])]
for text in ['Plafonner chaque position à 20 % et revoir en priorité AFBK.', 'Surveiller CLDX, dont le bêta et le drawdown sont élevés.', 'Ajouter des titres défensifs comme UTLG et TLCM pour réduire la sensibilité aux corrections.', 'Déclencher une revue si la perte hebdomadaire dépasse la VaR de 3,2 % ou si le drawdown dépasse -20 %.', 'Diversifier au-delà de la Finance, qui représente 34,8 % du portefeuille.']: story.append(Paragraph('• '+text,styles['BodyFr']))
story += [Spacer(1,8),Paragraph('6. Limites',styles['H2Fr']),Paragraph("Les données sont simulées et les entreprises fictives. La période est courte, hebdomadaire et sans frais de transaction ni effet de change. Les poids sont considérés constants ; les optimisations utilisent l’historique observé et sont donc susceptibles d’être surévaluées. Les résultats illustrent une méthode d’analyse et ne constituent pas un conseil d’investissement.",styles['BodyFr']),Spacer(1,14),Paragraph('Source : fichiers CSV versionnés dans results/ · Dernière mise à jour : 12 novembre 2026',styles['BodyFr'])]
doc.build(story)
print(out)
